begin;
set local plpgsql.check_asserts=on;
do $$
declare uid uuid:=gen_random_uuid(); sess uuid:=gen_random_uuid(); sid uuid; pid uuid; aid uuid; opt uuid; bid uuid; response jsonb; quote jsonb; rejected boolean;
  test_date date:=(clock_timestamp() at time zone 'Africa/Johannesburg')::date+80;
begin
  assert (select count(*)=16 from public.spa_services where deleted_at is null),'All sixteen published services imported';
  assert (select count(*)>=7 from public.spa_addons),'Published add-on therapies and extras imported';
  assert (select count(*)>=4 from public.spa_promotions),'All four promotions imported';
  assert exists(select 1 from public.spa_promotions p,jsonb_array_elements(p.pricing) rate where p.name='Group Wellness Special' and rate->>'kind'='discount' and rate->>'discount_percent'='20'),'Group discount retained';
  assert exists(select 1 from public.spa_addons a where a.name='Manual Lymph Drainage' and jsonb_array_length(a.pricing)=2),'Add-on duration prices retained';
  rejected:=false;begin perform public.spa_admin_save_service('{}');exception when insufficient_privilege then rejected:=true;end;assert rejected,'Guest service writes denied';
  rejected:=false;begin perform public.spa_admin_save_promotion('{}');exception when insufficient_privilege then rejected:=true;end;assert rejected,'Guest promotion writes denied';
  rejected:=false;begin perform public.spa_admin_delete_catalogue('service',gen_random_uuid());exception when insufficient_privilege then rejected:=true;end;assert rejected,'Guest deletes denied';
  insert into auth.users(id,email) values(uid,'qa-catalogue@example.invalid');
  insert into auth.sessions(id,user_id) values(sess,uid);
  insert into public.spa_admins(user_id,role) values(uid,'admin');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sess)::text,true);
  assert exists(select 1 from jsonb_array_elements(public.spa_admin_data()->'staff') s where s->>'email'='adivhahomudau3@gmail.com' and s->>'role'='owner'),'Real owner appears in staff';
  response:=public.spa_admin_save_service('{"name":"QA catalogue service","category":"massages","description":"Description","inclusions":["Included"],"base_price_cents":15000,"preparation_minutes":0,"active":true,"options":[{"duration":30,"price_cents":15000,"price_people":1},{"duration":60,"price_cents":30000,"price_people":1}]}');
  sid:=(response->>'id')::uuid;
  assert (select count(*)=2 from public.spa_options where service_id=sid and active),'Duration options saved atomically';
  perform public.spa_admin_save_service(jsonb_build_object('id',sid,'name','QA catalogue service','category','facials','base_price_cents',17000,'options','[{"duration":60,"price_cents":32000,"price_people":1}]'::jsonb));
  assert (select category='facials' and base_price_cents=17000 from public.spa_services where id=sid),'Service fields editable';
  assert (select count(*)=1 from public.spa_options where service_id=sid and active),'Deselected duration disabled';
  rejected:=false;begin perform public.spa_admin_save_service('{"name":"QA catalogue service","category":"other","options":[]}');exception when raise_exception then rejected:=true;end;assert rejected,'Duplicate service names denied';
  response:=public.spa_admin_save_promotion('{"name":"QA promotion","description":"Offer","inclusions":["Massage","Drink"],"pricing":[{"label":"Two people","kind":"fixed","price_cents":50000,"unit":"per_couple"},{"label":"Groups of ten","kind":"discount","discount_percent":20,"unit":"per_group"}],"starts_on":"2026-01-01","ends_on":"2027-12-31","active":true}');
  pid:=(response->>'id')::uuid;
  assert (select jsonb_array_length(pricing)=2 and cardinality(inclusions)=2 from public.spa_promotions where id=pid),'Promotion prices and inclusions saved';
  rejected:=false;begin perform public.spa_admin_save_promotion(jsonb_build_object('id',pid,'name','QA promotion','pricing','[{"label":"Bad","kind":"discount","discount_percent":120,"unit":"flat"}]'::jsonb));exception when raise_exception then rejected:=true;end;assert rejected,'Invalid discount denied';
  assert (select jsonb_array_length(pricing)=2 from public.spa_promotions where id=pid),'Failed promotion update preserves prices';
  response:=public.spa_admin_save_addon(jsonb_build_object('name','QA extra','price_cents',10000,'service_ids',array[sid],'promotion_ids',array[pid],'pricing','[{"label":"Price","kind":"fixed","price_cents":10000,"unit":"per_person"}]'::jsonb));
  aid:=(response->>'id')::uuid;
  assert (select count(*)=1 from public.spa_addon_services where addon_id=aid),'Service association';
  assert (select count(*)=1 from public.spa_addon_promotions where addon_id=aid),'Promotion association';
  perform public.spa_admin_delete_catalogue('addon',aid);
  assert not exists(select 1 from public.spa_addons where id=aid),'Add-on deletable';
  assert not exists(select 1 from public.spa_addon_promotions where addon_id=aid),'Deleted add-on links cleaned';
  select id into opt from public.spa_options where service_id=sid and active;
  quote:=public.spa_quote(opt,test_date,'10:00',1);
  response:=public.spa_submit(opt,test_date,'10:00',1,'QA catalogue reservation','0000000000','qa-catalogue@example.invalid',quote->>'quote',gen_random_uuid());
  select id into bid from public.spa_bookings where reference=response->>'reference';
  rejected:=false;begin perform public.spa_admin_delete_catalogue('service',sid);exception when raise_exception then rejected:=true;end;assert rejected,'Active reservation prevents deletion';
  perform public.spa_admin_change('status',jsonb_build_object('id',bid,'status','cancelled'));
  perform public.spa_admin_delete_catalogue('service',sid);
  assert (select deleted_at is not null and not active from public.spa_services where id=sid),'Service removed from catalogue';
  assert exists(select 1 from public.spa_bookings where id=bid),'Booking history preserved';
  assert not exists(select 1 from jsonb_array_elements(public.spa_admin_data()->'services') s where s->>'id'=sid::text),'Deleted service absent from admin table';
  response:=public.spa_admin_save_service('{"name":"QA catalogue service","category":"massages","options":[{"duration":30,"price_cents":17000,"price_people":1}]}');
  assert response->>'id'=sid::text,'Deleted service can be added again without a duplicate-name failure';
  assert (select deleted_at is null from public.spa_services where id=sid),'Re-added service restored to catalogue';
  assert exists(select 1 from public.spa_bookings where id=bid),'Re-adding preserves appointment history';
  perform public.spa_admin_delete_catalogue('service',sid);
  perform public.spa_admin_delete_catalogue('promotion',pid);
  assert not exists(select 1 from public.spa_promotions where id=pid),'Promotion deletable';
  assert not has_table_privilege('anon','public.spa_promotions','select');
  assert not has_table_privilege('authenticated','public.spa_promotions','insert');
  assert not has_function_privilege('anon','public.spa_admin_delete_catalogue(text,uuid)','execute');
  update public.spa_admins set active=false where user_id=uid;
end $$;
set local role authenticated;
do $$ begin assert (select count(*)=0 from public.spa_promotions),'RLS hides promotion management from unauthorised users';assert (select count(*)=0 from public.spa_addon_promotions),'RLS hides promotion links';end $$;
reset role;
rollback;
select 'PASS: published catalogue imported; owner staff row; service, add-on and promotion create/edit/delete; price variants; discounts; service links; invalid and guest writes denied; deletion protects active reservations and preserves history; RLS. Fixtures rolled back.' as result;
